I={'frame':'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8M12 17v4"/>','home':'<path d="M3 11l9-7 9 7v9a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/>','biz':'<path d="M4 9h16l-1-5H5zM5 9v11h14V9M9 20v-6h6v6"/>','folder':'<path d="M3 6a1 1 0 0 1 1-1h5l2 2h9a1 1 0 0 1 1 1v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z"/>','sync':'<path d="M4 12a8 8 0 0 1 14-5l2 2M20 12a8 8 0 0 1-14 5l-2-2M20 4v5h-5M4 20v-5h5"/>','clock':'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>','fit':'<rect x="3" y="3" width="18" height="18" rx="2"/><rect x="7" y="7" width="10" height="10" rx="1"/>','logo':'<path d="M4 6h16v12H4z"/><path d="M14 9h4v3h-4z"/>','user':'<circle cx="9" cy="8" r="3"/><circle cx="17" cy="9" r="2.5"/><path d="M3 20a6 6 0 0 1 12 0M15 20a4 4 0 0 1 6-3"/>','bolt':'<path d="M13 2L4 14h7l-1 8 9-12h-7z"/>','help':'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 3.5 2.3c-.7.3-1 .9-1 1.7M12 17h.01"/>','play':'<path d="M7 4l13 8-13 8z"/>'}
def ic(n):return f'<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">{I[n]}</svg>'
NAV=[('index.html','Home'),('home.html','For Home'),('business.html','For Business'),('how-it-works.html','How it works'),('features.html','Features'),('devices.html','Devices'),('screenshots.html','Screenshots'),('faq.html','FAQ'),('help.html','Help')]
PLAY='<a class="btn play" href="#">'+ic('play')+'<span><small>GET IT ON</small>Google Play</span></a><p class="soon">Coming soon to Google Play · now in closed testing</p>'
CSS='''*{box-sizing:border-box}body{margin:0;font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;color:#111827;background:#fff;line-height:1.6}
a{color:inherit}h1,h2,h3{font-weight:700;letter-spacing:-.01em;line-height:1.2;margin:0 0 .4em;color:#111827}
.w{max-width:1200px;margin:auto;padding:0 20px}.ic{width:26px;height:26px}
header{position:sticky;top:0;z-index:9;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.1),0 1px 2px -1px rgba(0,0,0,.1)}
header .w{display:flex;align-items:center;justify-content:space-between;height:60px}.brand{display:flex;gap:10px;align-items:center;font-weight:700;text-decoration:none;font-size:17px}
.brand i{width:32px;height:32px;border-radius:50%;background:linear-gradient(135deg,#fb923c,#ea580c);display:block;box-shadow:inset 0 0 0 7px #fff3,0 1px 2px #0002}
nav a{text-decoration:none;font-size:14px;font-weight:500;color:#4b5563;margin-left:20px}nav a:hover,nav a.on{color:#ea580c}
.hero{background:linear-gradient(135deg,#fff7ed,#fefce8);text-align:center;padding:72px 0 76px}
.hero h1{font-size:clamp(32px,4.5vw,48px)}.hero p.lead{font-size:19px;color:#374151;max-width:640px;margin:0 auto}.acc{color:#ea580c}
.btn{display:inline-flex;align-items:center;gap:10px;text-decoration:none;border-radius:10px;padding:10px 20px;font-weight:600;font-size:15px}
.play{background:#111827;color:#fff;margin-top:26px}.play small{display:block;font-size:10px;letter-spacing:.08em;font-weight:500;opacity:.8}.play span{line-height:1.15;text-align:left}.soon{font-size:13px;color:#6b7280;margin:10px 0 0}
.btn.alt{background:#ea580c;color:#fff}
section{padding:64px 0}h2{font-size:clamp(26px,3.2vw,36px);text-align:center}.sub{color:#4b5563;font-size:17px;max-width:620px;margin:0 auto 40px;text-align:center}
.g{display:grid;gap:20px;grid-template-columns:repeat(auto-fit,minmax(230px,1fr))}
.card{background:#fff;border:1px solid #f3f4f6;border-radius:12px;padding:26px 22px;text-align:center;box-shadow:0 1px 3px rgba(0,0,0,.08),0 1px 2px -1px rgba(0,0,0,.08);transition:box-shadow .2s}
.card:hover{box-shadow:0 10px 15px -3px rgba(0,0,0,.1)}.card .ic{width:52px;height:52px;padding:12px;border-radius:12px;color:#fff;background:linear-gradient(160deg,#fb923c,#ea580c);margin:0 auto 14px;display:block;box-shadow:0 2px 4px rgba(234,88,12,.3)}
.card h3{font-size:16px;font-weight:600}.card p{color:#6b7280;margin:0;font-size:14px}
.doors{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:48px}.door{border-radius:12px;padding:36px;text-decoration:none;text-align:center;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.1);border:1px solid #f3f4f6;transition:box-shadow .2s}
.door:hover{box-shadow:0 10px 15px -3px rgba(0,0,0,.12)}.door h2{font-size:24px}.door p{color:#6b7280;margin:0}.door .ic{width:64px;height:64px;padding:15px;border-radius:14px;color:#fff;display:block;margin:0 auto 16px}
.d1 .ic{background:linear-gradient(160deg,#fb923c,#ea580c)}.d2 .ic{background:linear-gradient(160deg,#60a5fa,#2563eb)}
.steps{counter-reset:s}.step{counter-increment:s}.step:before{content:counter(s);display:grid;place-items:center;width:44px;height:44px;border-radius:12px;background:linear-gradient(160deg,#fb923c,#ea580c);color:#fff;font-weight:700;margin:0 auto 14px}
.dev{aspect-ratio:16/10;border-radius:14px;border:8px solid #1f2937;position:relative;overflow:hidden;box-shadow:0 4px 12px rgba(0,0,0,.12)}
.dev.ph{aspect-ratio:9/17;border-radius:24px;max-width:230px;margin:auto;width:100%}.dev span{position:absolute;bottom:8px;left:10px;font-size:11px;background:rgba(0,0,0,.45);color:#fff;padding:2px 8px;border-radius:6px}
.p1{background:linear-gradient(135deg,#fed7aa,#f97316)}.p2{background:linear-gradient(160deg,#bfdbfe,#3b82f6)}.p3{background:linear-gradient(120deg,#bbf7d0,#22c55e)}.p4{background:linear-gradient(200deg,#fef08a,#f59e0b)}
.dark{background:#f9fafb}.dark .sub{color:#4b5563}
details{border:1px solid #f3f4f6;border-radius:12px;padding:16px 20px;margin-bottom:12px;box-shadow:0 1px 2px rgba(0,0,0,.06)}summary{font-weight:600;cursor:pointer}details p{color:#4b5563;margin:.5em 0 0}
.draft{display:inline-block;background:#ffedd5;color:#c2410c;font-weight:700;padding:3px 10px;border-radius:6px;letter-spacing:.08em;font-size:12px}
footer{background:#f9fafb;border-top:1px solid #e5e7eb;color:#4b5563;padding:40px 0 32px;font-size:14px;text-align:center}footer .w>div:first-child{padding-bottom:18px;border-bottom:1px solid #e5e7eb;margin-bottom:18px}
footer b{color:#111827!important;font-size:16px}footer a{text-decoration:none;margin:0 9px;color:#4b5563}footer .w>div:last-child a:first-child,footer a[href^=mailto]{color:#ea580c}footer a:hover{color:#ea580c}
.prose{max-width:760px}.prose h3{margin-top:28px}
@media(max-width:820px){nav{display:none}.doors{grid-template-columns:1fr}.hero{padding:52px 0}section{padding:48px 0}}'''
def page(f,title,body):
  nav=''.join(f'<a href="{h}"{" class=on" if h==f else ""}>{t}</a>' for h,t in NAV[1:])
  fl=''.join(f'<a href="{h}">{t}</a>' for h,t in NAV+[('privacy.html','Privacy')])
  open(f,'w').write(f'''<!doctype html><html lang=en><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>{title} · SceneBuzz</title>
<link rel=stylesheet href=style.css></head><body>
<header><div class=w><a class=brand href=index.html><i></i>SceneBuzz</a><nav>{nav}</nav></div></header>{body}
<footer><div class=w><div><b style="color:#f4efe8">SceneBuzz</b> · an Android app · <a href="mailto:support@389.one">support@389.one</a></div><div>{fl}</div></div></footer></body></html>''')
def hero(t,l,extra=PLAY):return f'<div class=hero><div class=w><h1>{t}</h1><p class=lead>{l}</p>{extra}</div></div>'
def cards(items):return '<div class=g>'+''.join(f'<div class=card>{ic(i)}<h3>{h}</h3><p>{p}</p></div>' for i,h,p in items)+'</div>'
def sec(h,s,inner,cls=''):return f'<section class="{cls}"><div class=w><h2>{h}</h2><p class=sub>{s}</p>{inner}</div></section>'
F=[('folder','Your folders','Pick your Camera folder in one tap, or browse other folders.'),('sync','Library sync','Keeps your slideshow up to date with your library.'),('clock','Your pace','Photo time from 30s default up to 180s; 2s transitions by default.'),('fit','Fit whole photo','Nothing cropped. A dimmed or blurred backdrop fills the edges.'),('logo','Video logo overlays','Put your logo on top of videos.'),('user','Profiles','Separate setups like “Living Room” or “Front Counter”.'),('bolt','Fast startup','Opens straight into your show.'),('help','In-app Help','Answers right inside the app.')]
page('index.html','Home',hero('Old screens.<br><span class=acc>New scenes.</span>','SceneBuzz turns an Android device, even an old Kindle Fire, a Chromebook or your newest tablet, into a photo-and-video slideshow, digital frame or signage screen.')+
 f'<div class=w><div class=doors><a class="door d1" href=home.html>{ic("home")}<h2>For Home</h2><p>A family frame on an old tablet or TV. Relive the trips.</p></a><a class="door d2" href=business.html>{ic("biz")}<h2>For Business</h2><p>Menus, promos and lobby screens without the signage bill.</p></a></div></div>'+
 sec('Simple by design','Pick a folder, press play. Everything else is optional.',cards(F[:4]))+
 sec('Works on what you already own','Kindle Fire tablets, Chromebooks and newer Android phones and tablets.','<div class=g><div class="dev p1"><span>Placeholder</span></div><div class="dev p2"><span>Placeholder</span></div><div class="dev p3"><span>Placeholder</span></div></div><p style="margin-top:36px;text-align:center"><a class="btn alt" href=devices.html>See devices →</a></p>','dark'))
page('home.html','For Home',hero('The family frame <span class=acc>you already own.</span>','Give that old tablet in the drawer a second life. Fill it with trips, birthdays and everyday moments.')+
 sec('Made for the living room','Set it up once, then just enjoy.',cards([('frame','Old tablet or TV','Turn a spare Android tablet or TV device into a digital photo frame.'),('play','Relive trips','Photos and videos from your Camera folder play on their own.'),('user','For grandparents','Set it up and hand it over. It just plays.'),('fit','Every photo whole','Portraits and panoramas shown in full, with a soft blurred backdrop.')]))+
 sec('Calm, not cluttered','Slow photo times up to 180 seconds, gentle 2-second transitions by default.','<div class=g><div class="dev p4"><span>Placeholder</span></div><div class="dev p1"><span>Placeholder</span></div></div>','dark'))
page('business.html','For Business',hero('Signage, <span class=acc>without the setup.</span>','Run menus, promos and lobby loops on an Android screen you already have.')+
 sec('Built for small spaces','A screen that sells for you.',cards([('biz','Cafe menus and promos','Loop today’s specials and offers.'),('frame','Salon and lobby screens','Show your work while guests wait.'),('home','Real estate open house','A gallery of the listing on a tablet in the kitchen.'),('play','Event displays','Photo and video loops for the venue.'),('logo','Small retail','Add your logo to every video.'),('user','One profile per screen','“Window”, “Counter”, “Lobby”, each with its own settings.')]))+
 sec('Your brand on screen','Video logo overlays keep every clip on-brand.','<div class=g><div class="dev p2"><span>Placeholder</span></div><div class="dev p3"><span>Placeholder</span></div></div>','dark'))
page('how-it-works.html','How it works',hero('Up and running <span class=acc>in minutes.</span>','Four steps. No account maze.','')+
 sec('How it works','',f'<div class="g steps">'+''.join(f'<div class="card step"><h3>{a}</h3><p>{b}</p></div>' for a,b in [('Install','Get SceneBuzz on your Android device.'),('Pick a folder','Tap your Camera folder, or browse other folders.'),('Tune it','Set photo time, transitions and fit mode.'),('Press play','Your show starts. Sync keeps it fresh.')])+'</div>'+PLAY.replace('class=soon','class=soon style="color:#6d655c"')))
page('features.html','Features',hero('Everything you need. <span class=acc>Nothing you don’t.</span>','The full feature list.','')+sec('Features','',cards(F)))
page('devices.html','Devices',hero('Your devices, <span class=acc>reborn.</span>','SceneBuzz runs on Android, from older devices to the latest models.','')+
 sec('Supported devices','',cards([('frame','Kindle Fire & old tablets','The tablet in the drawer makes a perfect frame.'),('frame','Chromebook','A big, bright screen for a slideshow or signage.'),('frame','Fold & newer phones','Prop it open and let it play.')])))
page('screenshots.html','Screenshots',hero('A look <span class=acc>inside.</span>','Real screenshots coming soon. Below are placeholders.','')+
 sec('Screenshots','<span class=draft>PLACEHOLDERS</span>','<div class=g>'+''.join(f'<div class="dev ph {c}"><span>Placeholder · {t}</span></div>' for c,t in [('p1','Slideshow'),('p2','Folder picker'),('p3','Settings'),('p4','Profiles')])+'</div>'))
Q=[('Which devices does it run on?','Android devices, including old Kindle Fire tablets, Chromebooks and newer phones and tablets.'),('Where do photos come from?','Local folders on your device. Pick the Camera folder, or browse other folders.'),('Will my photos be cropped?','Not with “fit whole photo”. The edges get a dimmed or blurred version of the photo.'),('How long is each photo shown?','30 seconds by default, adjustable up to 180 seconds. Transitions are 2 seconds by default.'),('Can I run more than one setup?','Yes. Create profiles like “Living Room”.'),('When is it available?','SceneBuzz is in Google Play closed testing. The public release is coming soon.')]
page('faq.html','FAQ',hero('Questions, <span class=acc>answered.</span>','','')+'<section><div class="w prose">'+''.join(f'<details open><summary>{q}</summary><p>{a}</p></details>' for q,a in Q)+'</div></section>')
page('help.html','Help',hero('Need a hand?','SceneBuzz has Help built into the app. For anything else, email us.','<a class="btn play" href="mailto:support@389.one">support@389.one</a>')+
 sec('Quick help','',cards([('folder','Choosing photos','Settings → folders: Camera, or browse other folders.'),('clock','Timing','Adjust photo time (up to 180s) and transition length.'),('help','In-app Help','Open Help from the app menu.')])))
page('privacy.html','Privacy',hero('Privacy policy','<span class=draft>DRAFT</span> Placeholder text. Not final.','')+'<section><div class="w prose"><span class=draft>DRAFT</span><h3>Overview</h3><p>[Placeholder] This page will describe how SceneBuzz (com.sceneframe.app) handles data.</p><h3>Photos and videos</h3><p>[Placeholder] SceneBuzz plays media from local folders you choose on your device.</p><h3>Contact</h3><p>Questions: <a href="mailto:support@389.one">support@389.one</a></p></div></section>')
